begin
             if at(74,19) then
             if wantenter('WATER FIELD') then begin
                with party do begin
                   map := 10; xaxis := 25; yaxis := 70;
                end;
                load;
                if party.etc[38] and bit4 > 0 then map[40,56] := 44;
             end;
             if at(23,62) then
             if wantenter('NOTICE') then begin
                with party do begin
                   map := 17; xaxis := 56; yaxis := 94;
                end;
                load;
             end;
             if at(96,42) then
             if wantenter('LOCKUP') then begin
                with party do begin
                   map := 18; xaxis := 25; yaxis := 94;
                end;
                load;
             end;
          end

if wantenter('WIVERN') then begin
              with party do begin
                 map := 16; xaxis := 20; yaxis := 9;
              end;
              load;
           end

begin
              if y = 46 then begin
                 y := 50;
                 scroll(TRUE);
              end;
              if y = 49 then begin
                 y := 45;
                 scroll(TRUE);
              end;
              if y = 71 then begin
                 if wantexit then begin
                    with party do begin
                       xaxis := 74; yaxis := 20; map := 3;
                    end;
                    load;
                 end
                 else begin
                    dec(y); scroll(TRUE);
                 end;
              end;
           end

begin
              Clear;
              if y = 95 then
              if wantexit then begin
                 with party do begin
                    xaxis := 96; yaxis := 43; map := 3;
                 end;
                 load; scroll(TRUE);
              end
              else begin
                 dec(y); scroll(TRUE);
              end;
              if on(22,41) then begin
                 map[22,41] := 44; map[21,41] := 52;
              end;
              if on(21,41) and (party.etc[39] and bit3 = 0) then begin
                 if party.etc[1] = 0 then begin
                    party.etc[1] := 1;
                    scroll(true);
                 end;
                 Print(11,'미로속에서 소를 닮은 괴물이 나타났다');
                 for i := 1 to 4 do begin
                    if i > 1 then putimage(100,(i-1)*20,font^[map[x,y-(6-i)]],copyput);
                    putimage(100,i*20,chara^[37],andput);
                    putimage(100,i*20,chara^[9],orput);
                    if i < 4 then delay(1000);
                 end;
                 PressAnyKey;
                 enemynumber := 1;
                 joinenemy(1,53);
                 Displayenemies(TRUE);
                 BattleMode(FALSE);
                 party.etc[39] := party.etc[39] or bit3;
              end;
              if on(37,31) then begin
                 if party.etc[39] and bit2 > 0 then exit;
                 if party.etc[39] and bit1 > 0 then begin
                    if party.etc[5] > 0 then begin
                       j := player[1].level[3];
                       for i := 2 to 6 do
                       if player[i].name <> '' then begin
                          if player[i].level[3] > j then j := player[i].level[3];
                       end;
                       if j < 5 then begin
                          Print(7,' 당신이 나의 마음을 읽으려 하지만 아직 당신');
                          Print(7,'의 능력으로는 나의 마음을 끌어낼수는 없습니');
                          talk('다.');
                       end
                       else begin
                          Print(7,' 갑자기 Necromancer에게 대항 하고픈  결의가');
                          Print(7,'생기는 군요. 나도 당신들을 도와 그를 무찌르');
                          Print(7,'겠습니다.');
                          m[0] := '';
                          m[1] := '저도 원했던 바입니다';
                          m[2] := '말씀은 고맙지만 사양하겠습니다';
                          k := select(140,2,2,FALSE,TRUE);
                          if k = 0 then exit;
                          party.etc[39] := party.etc[39] or bit2;
                          if k = 2 then exit;
                          k := ReturnJoinMember;
                          if k = 1 then exit;
                          join(43,k);
                          with player[k] do begin
                             name := 'Spica';
                             sex := female;
                             class := 3;
                             strength := 10;
                             mentality := 17;
                             concentration := 20;;
                             endurance := 9;
                             resistance := 15;
                             agility := 7;
                             accuracy[1] := 8;
                             accuracy[2] := 15;
                             accuracy[3] := 20;
                             luck := 10;
                             poison := 0;
                             unconscious := 0;
                             dead := 0;
                             level[1] := 11;
                             level[2] := 6;
                             level[3] := 11;
                             hp := endurance * level[1];
                             sp := mentality * level[2];
                             esp := concentration * level[3];
                             ac := 3;
                             weapon := 1;
                             shield := 1;
                             armor := 1;
                             wea_power := 5;
                             shi_power := 1;
                             arm_power := 2;
                          end;
                          Display_Condition;
                       end;
                    end
                    else begin
                       Print(7,' 지체할 시간이 없습니다. 신속히 행동을 취하');
                       talk('십시오.');
                    end;
                 end;
                 if party.etc[39] and bit1 = 0 then begin
                    Print(11,'여기에는 어떤 여자가 수도하고 있었다');
                    PressAnyKey;
                    Print(7,' 나는 이곳 LOCKUP이 적들에게 점령되기전  부');
                    Print(7,'터 여기서 수도하고 있는 Spica란 사람입니다');
                    Print(7,' 오랜 수도 끝에 나는 초자연력의 존재와 사용');
                    Print(7,'법을 알게 되었습니다.  대충 요약하면 이렇습');
                    Print(7,'니다.');
                    PressAnyKey;
                    Print(7,'');
                    Print(15,'투  시 : 변화의 여지가 있는 지역을 탐지');
                    Print(15,'예  언 : 다음의 할 일을 알아냄');
                    Print(15,'독  심 : 남의 마음을 자기쪽으로 끌어들임');
                    Print(15,'천리안 : 능력에 따라 먼곳의 광경을 봄');
                    Print(15,'염  력 : 주위 환경 조절에 의한 공격');
                    PressAnyKey;
                    Print(7,' 이것으로 Necromancer에게 도전 하십시오. 또');
                    Print(7,'한,  그도 초자연력의 존재를 알고있고 사용할');
                    Print(7,'줄 안다는걸 염두에 두고 사용하십시오.');
                    PressAnyKey;
                    party.etc[39] := party.etc[39] or bit1;
                 end;
              end;
              if (x = 31) and (party.etc[15] < 4) then begin
                 if party.etc[1] = 0 then begin
                    party.etc[1] := 1;
                    scroll(true);
                 end;
                 message(11,'당신은 여기가 Huge Dragon의 거처임을 느꼈다');
                 face := 6;
                 for i := 1 to 6 do begin
                    inc(x);
                    scroll(TRUE);
                    delay(200);
                 end;
                 face := 4;
                 for i := y+1 to 13 do begin
                    y := i;
                    scroll(TRUE);
                    delay(200);
                 end;
                 face := 5;
                 Silent_Scroll;
                 for i := 4 to 6 do begin
                    putimage(20*i,20,chara^[4*(i-4)+39],andput);
                    putimage(20*i,20,chara^[4*(i-4)+11],orput);
                 end;
                 delay(2000);
                 for j := 1 to 3 do begin
                    for i := 4 to 6 do begin
                       putimage(20*i,20*(j+1),font^[43],copyput);
                       putimage(20*i,20*(j+1),chara^[4*(i-4)+39],andput);
                       putimage(20*i,20*(j+1),chara^[4*(i-4)+11],orput);
                    end;
                    for i := 4 to 6 do begin
                       putimage(20*i,20*j,font^[43],copyput);
                       putimage(20*i,20*j,chara^[4*(i-4)+38],andput);
                       putimage(20*i,20*j,chara^[4*(i-4)+10],orput);
                    end;
                    if j > 1 then
                    for i := 4 to 6 do putimage(20*i,20*(j-1),font^[43],copyput);
                    if j < 3 then delay(2000);
                 end;
                 PressAnyKey;
                 enemynumber := 7;
                 joinenemy(1,54);
                 enemy[1].name := 'Huge Dragon';
                 joinenemy(2,39);
                 with enemy[2] do begin
                    name := 'Dragon''s tail';
                    ac := 8;
                 end;
                 for i := 3 to 7 do joinenemy(i,random(3)+30);
                 Displayenemies(TRUE);
                 BattleMode(FALSE);
                 if party.etc[6] = 255 then exit;
                 if party.etc[6] = 0 then begin
                    Clear;
                    Print(15,'당신들은 Huge Dragon을 물리쳤다.');
                    Print(11,'그리고 당신은 이 임무에 성공했다.');
                    Print(15,'다시 WATER FIELD 의 군주에게로 돌아가라.');
                    PressAnyKey;
                    party.etc[15] := 4;
                    scroll(TRUE);
                 end
                 else begin
                    x := 25; y := 94;
                    scroll(TRUE);
                 end;
              end;
           end

begin
      if at(36,32) or at(38,33) or at(39,35) then train_center;
      if at(17,57) or at(12,59) or at(11,55) then grocery;
      if at(11,30) or at(11,32) or at(13,34) then weapon_shop;
      if at(33,60) or at(35,54) or at(41,58) then hospital;
      if at(11,16) then
         talk('NOTICE 동굴의 Hidra는 머리가 셋이나 달렸다더군요.');
      if at(14,18) then
         talk('NOTICE 동굴은 혼란스러운 미로라서 항상 주위를 염두에 두셔야 합니다.');
      if at(24,22) then
         talk('LOCKUP 동굴은 미로로 구성된 동굴이오.');
      if at(27,22) then
         talk('LOCKUP 속에 Minotaur는 Necromancer의 부하는 아닙니다.');
      if at(24,69) then begin
         Print(7,' LOCKUP 의 보스인 Huge Dragon은 아주 거대한');
         Print(7,'용이라는데,  그것의 꼬리 또한 강력한 무기라');
         Print(7,'서 조심해야 할것이오.');
         PressAnyKey;
      end;
      if at(37,16) then begin
         Print(7,' 고르곤 세자매의 힘은 Necromancer의 힘과 필');
         Print(7,'적하지만 중대한 약점이 하나 있소.');
         PressAnyKey;
      end;
      if at(40,18) then
         talk('Stheno 와 Euryale는 거의 불멸의 생명체 입니다.');
      if at(40,56) then begin
         hany := 20;
         Print(7,' 나는 LORE 특공대의 대장인 Lore Hunter 라고');
         Print(7,'하오. 여기서의 적들과는, 이제 대항하기가 혼');
         Print(7,'자서는 무리라고 판단했소. 그래서, 나는 여태');
         Print(7,'껏 여기서 새로운 영웅들을 기다리고 있었소.');
         Print(7,' 내가 당신의 일행에 끼게 되는걸 어떻게 생각');
         Print(7,'하오 ?');
         m[0] := '';
         m[1] := '우리도 그러기를 바라오';
         m[2] := '몸이 완전히 회복될때까지 기다리시오';
         k := select(145,2,2,FALSE,TRUE);
         if k = 2 then asyouwish;
         if k <> 1 then exit;
         k := ReturnJoinMember;
         if k = 1 then exit;
         join(39,k);
         with player[k] do begin
            name := 'Lore Hunter';
            class := 7;
            weapon := 5;
            shield := 2;
            armor := 1;
            wea_power := 15;
            shi_power := 2;
            arm_power := 2;
            ac := 4;
         end;
         Display_Condition;
         map[40,56] := 44;
         Silent_Scroll;
         party.etc[38] := party.etc[38] or bit4;
      end;
      if at(25,18) then
      case party.etc[15] of
         0 : begin
          Print(7,' 여기는 WATER FIELD 라는 성이오.  이곳이 당');
          Print(7,'신이 마지막으로 거칠 우리편의 성이오.');
          Print(7,' 차원의 틈을 통해 Necromancer가 내려 오던날');
          Print(7,'이 대륙은 거의 전부가 바다로 가라않았소. 하');
          Print(7,'지만  그때에 살아 남은 사람들은 아직 가라않');
          Print(7,'지 않은 이곳에 찾아와서 이 성을 건립했소.그');
          Print(7,'리고는  공이 컸던 나를 왕으로 추대했던 것이');
          Print(7,'오.');
          Print(7,' 당신도 생각하고 있다시피 이 대륙은 거의 물');
          Print(7,'로 덮혀있소.  하지만 이곳처럼 물이 차지않은');
          Print(7,'두곳에 Necromancer 는 이미 이 대륙의 지배를');
          Print(7,'위한 동굴을 만들었소. 그 두곳의 적들은 여타');
          Print(7,'의 대륙과는 비교가 안될 정도의  거대한 적들');
          Print(7,'이 많이 있소.');
          Print(7,' 우리로서는 더 이상 손을 쓸수가 없소.  이곳');
          Print(7,'사람들의 마지막 희망인  이 곳이 적들에게 점');
          Print(7,'령된다면 WIVERN 동굴로 이어지는 워터 게이트');
          Print(7,'를 통해 다른 대륙도 하나둘씩  점령되어 갈것');
          Print(7,'이오.');
          talk('');
          inc(party.etc[15]);
             end;
         1 : begin
          Print(7,' 먼저,  여기서 남서쪽의 어느 섬에 있는 동굴');
          Print(7,'인 NOTICE에 가서 보스인 Hidra를 물리쳐 주십');
          Print(7,'시오.');
          PressAnyKey;
             end;
         2 : begin
          Print(7,'Hidra를 물리치다니 ... 대단한 능력이오.');
          Print(11,'[ EXP + 150000 ]');
          Print(7,'');
          for i := 1 to 6 do if player[i].name <> '' then
             player[i].experience := player[i].experience + 150000;
          Print(7,'이제는 소문으로만 듣던 당신들의 능력을 믿을');
          Print(7,'수 있겠소.');
          PressAnyKey;
          inc(party.etc[15]);
             end;
         3 : begin
          Print(7,' 이번에는  대륙의 동쪽에 있는 LOCKUP 동굴속');
          Print(7,'의 Huge Dragon을 물리쳐 주시오.');
          PressAnyKey;
             end;
         4 : begin
          Print(7,'역시 위대한 영웅이오 !!');
          Print(11,'[ EXP + 300000 ]');
          Print(7,'');
          for i := 1 to 6 do if player[i].name <> '' then
             player[i].experience := player[i].experience + 300000;
          Print(7,'여기에 Swamp Key 가 있소.');
          PressAnyKey;
          inc(party.etc[15]);
             end;
         5 : begin
          Print(7,' Swamp Key 는 GAIA TERRA 의 스왐프 게이트를');
          Print(7,'여는데 사용되오.  거기서 늪의 대륙으로 가시');
          Print(7,'오. 늪의 대륙은 완전한 적들의 소굴이므로 매');
          Print(7,'우 주의하시오.');
          PressAnyKey;
             end;
      end;
          end
